sys_ui_page.client_script:
function actionOK() {

    //debugger;

    var ga = new GlideAjax('ClearComment'); // 指向Script Include
    ga.addParam('sysparm_name', 'clearCommentField'); // 指定方法名
    ga.addParam('sysparm_assign_to', g_form.getValue('assign_to')); // 传递字段ID

    ga.getXML(function parseResponse(response) {
        var result = response.responseXML.documentElement.getAttribute('answer');
        if (result == 'OK') {
            GlideModal.get().destroy();
            g_form.setValue('comment', '');
        } else {
            alert('Update failure! Please contact System Administrator!');
        }
    });

    return true;
}
